// Assume mat3 is mat<3, 3>
template<int nrows, int ncols>
struct mat {
    vec<ncols> rows[nrows] = {{}};
    vec<ncols>& operator[](const int idx);
    const vec<ncols>& operator[](const int idx) const;
    double cofactor(int i, int j) const;
};

typedef mat<3, 3> mat3;

mat3 mat3_invert(const mat3& m) {
    // Compute determinant
    double det = m[0][0] * (m[1][1] * m[2][2] - m[1][2] * m[2][1])
               - m[0][1] * (m[1][0] * m[2][2] - m[1][2] * m[2][0])
               + m[0][2] * (m[1][0] * m[2][1] - m[1][1] * m[2][0]);

    if (std::abs(det) < 1e-10) {
        // Return zero matrix if not invertible
        return mat3();
    }

    // Compute adjugate matrix
    mat3 adjugate;
    for (int i = 0; i < 3; ++i) {
        for (int j = 0; j < 3; ++j) {
            adjugate[i][j] = m.cofactor(j, i); // Transpose by swapping i and j
        }
    }

    // Divide adjugate by determinant
    for (int i = 0; i < 3; ++i) {
        for (int j = 0; j < 3; ++j) {
            adjugate[i][j] /= det;
        }
    }

    return adjugate;
}

// Assume mat3 is mat<3, 3> and cofactor(i, j) exists
mat3 mat3_invert(const mat3& m) {
    // Compute determinant
    double det = m[0][0] * (m[1][1] * m[2][2] - m[1][2] * m[2][1])
               - m[0][1] * (m[1][0] * m[2][2] - m[1][2] * m[2][0])
               + m[0][2] * (m[1][0] * m[2][1] - m[1][1] * m[2][0]);

    if (std::abs(det) < 1e-10) {
