mat3 mat3_invert(const mat3& m) {
    // Compute determinant
    double det = m[0][0] * (m[1][1] * m[2][2] - m[1][2] * m[2][1])
               - m[0][1] * (m[1][0] * m[2][2] - m[1][2] * m[2][0])
               + m[0][2] * (m[1][0] * m[2][1] - m[1][1] * m[2][0]);

    if (std::abs(det) < 1e-10) {
        // Return zero matrix if not invertible
        return mat3();
    }

    // Compute adjugate matrix
    mat3 adjugate;
    for (int i = 0; i < 3; ++i) {
        for (int j = 0; j < 3; ++j) {
            // Compute minor matrix
            double minor[2][2];
            int minor_row = 0;
            for (int row = 0; row < 3; ++row) {
                if (row == i) continue;
                int minor_col = 0;
                for (int col = 0; col < 3; ++col) {
                    if (col == j) continue;
                    minor[minor_row][minor_col] = m[row][col];
                    minor_col++;
                }
                minor_row++;
            }
            // Compute cofactor
            double minor_det = minor[0][0] * minor[1][1] - minor[0][1] * minor[1][0];
            double cofactor = ((i + j) % 2 == 0 ? 1 : -1) * minor_det;
            adjugate[j][i] = cofactor; // Transpose by swapping i and j
        }
    }

    // Divide adjugate by determinant
    for (int i = 0; i < 3; ++i) {
        for (int j = 0; j < 3; ++j) {
            adjugate[i][j] /= det;
        }
    }

    return adjugate;
}
